# File converter tools (images, PDF, spreadsheets)
PRIV="<p class='priv'>🔒 Your files never leave your device. Conversion runs entirely in your browser — nothing is uploaded to any server.</p>"
def dropzone(accept,multiple,label):
    return f"<label class='drop' id='drop'><input type='file' accept='{accept}' {'multiple' if multiple else ''} hidden><b>{label}</b><span>or drag &amp; drop {'files' if multiple else 'a file'} here</span></label>"
def imgconv(src,dst,accept,mime,ext,quality):
    q=("<label for='q'>Quality: <output id='qv'>90</output>%</label><input id='q' type='range' min='40' max='100' value='90'>" if quality else "")
    bg=("<label for='bg'>Background for transparent areas</label><input id='bg' type='color' value='#ffffff'>" if mime=='image/jpeg' else "")
    ui=dropzone(accept,True,f"Choose {src} files")+f"<div class='opts'>{q}{bg}</div><p id='status' class='status'></p><div id='out'></div>"+PRIV
    js=f"""var qi=UI.$('#q');if(qi)qi.oninput=function(){{UI.$('#qv').textContent=qi.value}};
UI.drop(UI.$('#drop'),{{multiple:true,onFiles:async function(fs){{var out=[];for(var i=0;i<fs.length;i++){{UI.status('Converting '+(i+1)+' of '+fs.length+'…');try{{var img=await UI.decode(fs[i]);var b=await UI.toBlob(img,{{type:'{mime}',quality:qi?qi.value/100:undefined,bg:UI.$('#bg')?UI.$('#bg').value:null}});out.push({{name:DK.renameExt(fs[i].name,'{ext}'),blob:b,note:img.naturalWidth+'×'+img.naturalHeight}})}}catch(e){{UI.status(e.message,1);}}}}
UI.results(out);if(out.length)UI.status('Done — '+out.length+' file(s) converted.');}}}});"""
    return ui,js
T={}
def add(slug,cat,h,t,d,ui,js,g,libs=()):
    T[slug]=dict(cat=cat,h=h,t=t,d=d,ui=ui,js=js,g=g,libs=libs)
FAQ=lambda *qa:"<h2>FAQ</h2>"+"".join(f"<h3>{q}</h3><p>{a}</p>" for q,a in qa)
ui,js=imgconv("HEIC","JPG",".heic,.heif,image/heic,image/heif","image/jpeg","jpg",True)
add("heic-to-jpg","File converters","HEIC to JPG Converter","HEIC to JPG Converter – Free, Private, No Upload","Convert iPhone HEIC photos to JPG in your browser. Batch convert, choose quality, download as ZIP. Files never leave your device.",ui,js,
"<h2>What is a HEIC file?</h2><p>Since iOS 11, iPhones save photos as HEIC (High Efficiency Image Container). HEIC files are about half the size of JPGs at similar quality, but many Windows apps, websites and office tools still can't open them. Converting to JPG makes the photo work everywhere.</p><h2>How to convert HEIC to JPG</h2><ol><li>Click <b>Choose HEIC files</b> or drag photos onto the box. You can add many at once.</li><li>Pick a quality. 90% is visually identical to the original for almost all photos.</li><li>Download each JPG, or all of them as one ZIP.</li></ol><h2>Is it private?</h2><p>Yes. The decoder runs as JavaScript inside your browser tab. Your photos are not uploaded anywhere, which also makes conversion fast on a slow connection.</p>"+FAQ(("Why is the first conversion slower?","The HEIC decoder (about 1 MB) loads the first time you use it, then it's cached."),("Will I lose quality?","JPG is lossy, so a tiny amount of detail is discarded. At 90–100% quality the difference is not visible in normal viewing."),("Can I stop my iPhone from shooting HEIC?","Yes: Settings → Camera → Formats → Most Compatible. Or Settings → Photos → Transfer to Mac or PC → Automatic, which converts on transfer.")))
ui,js=imgconv("PNG","JPG",".png,image/png","image/jpeg","jpg",True)
add("png-to-jpg","File converters","PNG to JPG Converter","PNG to JPG Converter – Free Online, No Upload","Convert PNG images to JPG instantly in your browser. Set quality and background color for transparent areas. Batch convert and download as ZIP.",ui,js,
"<h2>Why convert PNG to JPG?</h2><p>PNG is lossless, so screenshots and photos saved as PNG are often several times larger than necessary. JPG compresses photos far better, which makes files easier to email, upload to forms with size limits, or put in a slide deck.</p><h2>Transparency</h2><p>JPG has no transparency. Transparent areas of your PNG are filled with the background color you choose (white by default), so logos don't turn black.</p><h2>When to keep PNG</h2><ul><li>Screenshots with small text, diagrams and logos with sharp edges stay crisper as PNG.</li><li>Images that need a transparent background.</li></ul>"+FAQ(("Is my image uploaded?","No. The conversion uses your browser's built-in canvas, so the image never leaves your computer."),("What quality should I use?","80–90% is a good balance of size and quality for photos. Use 95–100% for images with text.")))
ui,js=imgconv("JPG","PNG",".jpg,.jpeg,image/jpeg","image/png","png",False)
add("jpg-to-png","File converters","JPG to PNG Converter","JPG to PNG Converter – Free, Private, In-Browser","Convert JPG/JPEG images to PNG in your browser. Batch conversion, no upload, no sign-up, no watermark.",ui,js,
"<h2>JPG vs PNG</h2><p>JPG is best for photos; PNG is lossless and best for graphics, screenshots and images you'll edit repeatedly. Converting JPG to PNG doesn't restore detail lost to JPG compression, but it stops further loss every time you edit and save, and some upload forms and design tools require PNG.</p><h2>How to use it</h2><ol><li>Choose or drop one or more JPG files.</li><li>Each file is converted instantly in your browser.</li><li>Download individually or as a ZIP.</li></ol><p>Expect the PNG to be larger than the JPG—that's normal for lossless formats.</p>"+FAQ(("Does PNG make the background transparent?","No, the image keeps its original background. Transparency has to be added in an image editor."),("Is there a file limit?","No hard limit. Very large images (over ~50 megapixels) may exceed your browser's canvas limit.")))
ui,js=imgconv("WEBP","JPG",".webp,image/webp","image/jpeg","jpg",True)
add("webp-to-jpg","File converters","WEBP to JPG Converter","WEBP to JPG Converter – Free, No Upload","Convert WEBP images saved from websites to JPG so they open in any app. Batch convert in your browser; files never leave your device.",ui,js,
"<h2>Why can't I open WEBP files?</h2><p>WEBP is Google's web image format. Browsers love it, but older versions of Office, some photo viewers and many upload forms don't accept it. Converting to JPG fixes that in seconds.</p><h2>How to convert</h2><ol><li>Drop your .webp files onto the box.</li><li>Pick a quality (90% recommended) and a background color for any transparent areas.</li><li>Download the JPGs.</li></ol><h2>Need transparency?</h2><p>Use the <a href='/webp-to-png/'>WEBP to PNG converter</a> instead—PNG keeps transparent backgrounds.</p>"+FAQ(("Is it really free?","Yes, no sign-up and no watermark."),("Is it safe for work files?","Yes. The image is decoded and re-encoded locally in your browser; nothing is uploaded.")))
ui,js=imgconv("WEBP","PNG",".webp,image/webp","image/png","png",False)
add("webp-to-png","File converters","WEBP to PNG Converter","WEBP to PNG Converter – Keep Transparency, No Upload","Convert WEBP to PNG in your browser, keeping transparent backgrounds. Batch convert and download as ZIP. Private: nothing is uploaded.",ui,js,
"<h2>WEBP to PNG, transparency included</h2><p>Many logos and icons on the web are WEBP files with transparent backgrounds. Converting them to PNG keeps that transparency and makes them usable in PowerPoint, Google Slides, Canva and older image editors.</p><h2>Steps</h2><ol><li>Choose or drag .webp files.</li><li>They are converted to lossless PNG immediately.</li><li>Download one by one or as a ZIP.</li></ol><p>PNG files are usually larger than WEBP. If size matters more than transparency, use <a href='/webp-to-jpg/'>WEBP to JPG</a>.</p>"+FAQ(("Does it handle animated WEBP?","Only the first frame is converted, because PNG is a still-image format."),))
# compressor
ui=dropzone("image/jpeg,image/png,image/webp,.heic,.heif",True,"Choose images to compress")+"<div class='opts'><label for='q'>Quality: <output id='qv'>75</output>%</label><input id='q' type='range' min='30' max='95' value='75'><label for='mw'>Max width in px (optional, 0 = keep)</label><input id='mw' type='number' min='0' value='0'><label for='fmt'>Output format</label><select id='fmt'><option value='image/jpeg'>JPG (best compatibility)</option><option value='image/webp'>WEBP (smallest)</option></select></div><p id='status' class='status'></p><div id='out'></div>"+PRIV
js="""var qi=UI.$('#q');qi.oninput=function(){UI.$('#qv').textContent=qi.value};var last=[];
async function go(fs){last=fs;var out=[],tin=0,tout=0;for(var i=0;i<fs.length;i++){UI.status('Compressing '+(i+1)+' of '+fs.length+'…');try{var img=await UI.decode(fs[i]),mw=+UI.$('#mw').value||0,t=UI.$('#fmt').value;var b=await UI.toBlob(img,{type:t,quality:qi.value/100,w:mw&&mw<img.naturalWidth?mw:0,keep:true});
var keepOrig=b.size>=fs[i].size&&!mw&&fs[i].type===t;if(keepOrig)b=fs[i];tin+=fs[i].size;tout+=b.size;out.push({name:DK.renameExt(fs[i].name,t==='image/webp'?'webp':'jpg'),blob:b,note:keepOrig?'already optimal – original kept':'was '+DK.fileSize(fs[i].size)+' (−'+Math.round((1-b.size/fs[i].size)*100)+'%)'})}catch(e){UI.status(e.message,1)}}
UI.results(out);if(out.length)UI.status('Done. Total '+DK.fileSize(tin)+' → '+DK.fileSize(tout)+' ('+Math.round((1-tout/tin)*100)+'% smaller).')}
UI.drop(UI.$('#drop'),{multiple:true,onFiles:go});['#q','#mw','#fmt'].forEach(function(s){UI.$(s).addEventListener('change',function(){if(last.length)go(last)})});"""
add("image-compressor","File converters","Image Compressor","Image Compressor – Reduce JPG/PNG Size Online, No Upload","Compress JPG, PNG, WEBP and HEIC images in your browser. Adjust quality, set a max width, see the size saved. Files never leave your device.",ui,js,
"<h2>Make images small enough to email or upload</h2><p>Phone photos are often 3–8 MB. Most forms, CMSs and email systems work far better with images under 500 KB. This tool re-encodes your images at the quality you choose and can also scale them down, which is where most of the savings come from.</p><h2>Recommended settings</h2><ul><li><b>Email or chat:</b> quality 70–75%, max width 1600 px.</li><li><b>Website images:</b> quality 75–80%, max width 1920 px (or the width your layout actually uses), WEBP format.</li><li><b>Documents and slides:</b> quality 80%, max width 2000 px.</li></ul><h2>Why did a file not get smaller?</h2><p>If an image is already well compressed, re-encoding can make it bigger. In that case the tool keeps your original file and tells you so.</p>"+FAQ(("Are my images uploaded?","No. Compression happens with your browser's canvas encoder, on your device."),("Does it remove photo metadata?","Yes. Re-encoded images do not include EXIF data such as GPS location, which is good for privacy.")))
# resizer
ui=dropzone("image/jpeg,image/png,image/webp,.heic,.heif",True,"Choose images to resize")+"<div class='opts'><label for='w'>Width (px)</label><input id='w' type='number' min='1' value='1200'><label for='h'>Height (px, blank = auto)</label><input id='h' type='number' min='1'><label class='chk'><input id='k' type='checkbox' checked> Keep aspect ratio (fit inside)</label><label for='fmt'>Format</label><select id='fmt'><option value='same'>Same as original</option><option value='image/jpeg'>JPG</option><option value='image/png'>PNG</option><option value='image/webp'>WEBP</option></select></div><button class='btn' id='go' type='button'>Resize</button><p id='status' class='status'></p><div id='out'></div>"+PRIV
js="""var files=[];UI.drop(UI.$('#drop'),{multiple:true,onFiles:function(fs){files=fs;UI.status(fs.length+' file(s) ready. Set a size and click Resize.')}});
UI.$('#go').onclick=async function(){if(!files.length)return UI.status('Choose at least one image first.',1);var w=+UI.$('#w').value||0,h=+UI.$('#h').value||0;if(!w&&!h)return UI.status('Enter a width or height.',1);var out=[];
for(var i=0;i<files.length;i++){try{var img=await UI.decode(files[i]),f=UI.$('#fmt').value;if(f==='same')f=/png/.test(files[i].type)?'image/png':/webp/.test(files[i].type)?'image/webp':'image/jpeg';var keep=UI.$('#k').checked;
var b=await UI.toBlob(img,{type:f,quality:0.92,w:keep?w:(w||Math.round(img.naturalWidth*h/img.naturalHeight)),h:keep?h:(h||Math.round(img.naturalHeight*w/img.naturalWidth)),keep:keep});var im2=await createImageBitmap(b);
out.push({name:DK.renameExt(files[i].name,f.split('/')[1].replace('jpeg','jpg')),blob:b,note:img.naturalWidth+'×'+img.naturalHeight+' → '+im2.width+'×'+im2.height})}catch(e){UI.status(e.message,1)}}UI.results(out);if(out.length)UI.status('Done.')};"""
add("image-resizer","File converters","Image Resizer","Image Resizer – Resize Images to Exact Pixels, No Upload","Resize JPG, PNG, WEBP or HEIC images to exact pixel dimensions, keep the aspect ratio, batch process. Runs in your browser; nothing is uploaded.",ui,js,
"<h2>Resize to exact dimensions</h2><p>Enter a width, a height or both. With <b>Keep aspect ratio</b> on, the image is scaled to fit inside the box you set without distortion. Turn it off to force exact dimensions (the image is stretched).</p><h2>Common sizes</h2><ul><li>Profile photo (LinkedIn, Slack, Teams): 400 × 400</li><li>Email newsletter image: 600 px wide (1200 for retina)</li><li>Full-HD slide or web banner: 1920 × 1080</li><li>LinkedIn post image: 1200 × 627</li></ul>"+FAQ(("Can I enlarge an image?","Yes, but enlarging can't add detail, so the result looks softer."),("Is anything uploaded?","No—resizing uses your browser's canvas, locally.")))
# image to pdf
ui=dropzone("image/jpeg,image/png,image/webp,.heic,.heif",True,"Choose images")+"<ul id='list' class='sortlist'></ul><div class='opts'><label for='ps'>Page size</label><select id='ps'><option value='letter'>US Letter (8.5 × 11 in)</option><option value='a4'>A4</option><option value='fit'>Same as image</option></select><label for='or'>Orientation</label><select id='or'><option value='auto'>Auto (match each image)</option><option value='p'>Portrait</option><option value='l'>Landscape</option></select><label for='mg'>Margin</label><select id='mg'><option value='0'>None</option><option value='18' selected>Small (0.25 in)</option><option value='36'>Normal (0.5 in)</option></select></div><button class='btn' id='go' type='button'>Create PDF</button><p id='status' class='status'></p><div id='out'></div>"+PRIV
js="""var files=[];function draw(){var l=UI.$('#list');l.innerHTML='';files.forEach(function(f,i){var li=document.createElement('li');li.innerHTML='<span></span><button type="button" aria-label="Move up">↑</button><button type="button" aria-label="Move down">↓</button><button type="button" aria-label="Remove">✕</button>';li.firstChild.textContent=(i+1)+'. '+f.name;var b=li.querySelectorAll('button');
b[0].onclick=function(){if(i){files.splice(i-1,0,files.splice(i,1)[0]);draw()}};b[1].onclick=function(){if(i<files.length-1){files.splice(i+1,0,files.splice(i,1)[0]);draw()}};b[2].onclick=function(){files.splice(i,1);draw()};l.appendChild(li)})}
UI.drop(UI.$('#drop'),{multiple:true,onFiles:function(fs){files=files.concat(fs);draw()}});
UI.$('#go').onclick=async function(){if(!files.length)return UI.status('Add at least one image.',1);UI.status('Building PDF…');try{var doc=await PDFLib.PDFDocument.create(),S={letter:[612,792],a4:[595.28,841.89]},ps=UI.$('#ps').value,or=UI.$('#or').value,mg=+UI.$('#mg').value;
for(var i=0;i<files.length;i++){var img=await UI.decode(files[i]),b=await UI.toBlob(img,{type:'image/jpeg',quality:0.92}),e=await doc.embedJpg(await b.arrayBuffer()),iw=e.width*0.75,ih=e.height*0.75,pw,ph;
if(ps==='fit'){pw=iw+2*mg;ph=ih+2*mg}else{pw=S[ps][0];ph=S[ps][1];var land=or==='l'||(or==='auto'&&iw>ih);if(land){var t=pw;pw=ph;ph=t}}
var r=Math.min((pw-2*mg)/iw,(ph-2*mg)/ih,ps==='fit'?1:Infinity),w=iw*r,h=ih*r,p=doc.addPage([pw,ph]);p.drawImage(e,{x:(pw-w)/2,y:(ph-h)/2,width:w,height:h})}
var bytes=await doc.save();UI.results([{name:'images.pdf',blob:new Blob([bytes],{type:'application/pdf'}),note:files.length+' page(s)'}]);UI.status('PDF ready.')}catch(e){UI.status(e.message,1)}};"""
add("jpg-to-pdf","PDF tools","JPG to PDF Converter","JPG to PDF – Convert Images to PDF Free, No Upload","Combine JPG, PNG, WEBP or HEIC images into one PDF. Reorder pages, choose Letter or A4, set margins. Runs in your browser; files stay private.",ui,js,
"<h2>Turn photos and scans into one PDF</h2><p>Receipts for an expense report, photos of a signed form, screenshots for a ticket—most systems want a single PDF. Add your images, put them in order, and download one file.</p><h2>Options</h2><ul><li><b>Page size:</b> US Letter for US offices, A4 for international, or <i>Same as image</i> for a page that exactly fits each picture.</li><li><b>Orientation:</b> Auto rotates the page to match landscape images.</li><li><b>Margin:</b> a small margin looks better when printed.</li></ul><p>Images are scaled to fit the page without cropping or distortion.</p>"+FAQ(("Are my documents uploaded?","No. The PDF is generated in your browser with the open-source pdf-lib library."),("Can I add a PDF too?","To combine existing PDFs, use the <a href='/merge-pdf/'>Merge PDF</a> tool.")),libs=("pdf-lib.min.js",))
# merge pdf
ui=dropzone("application/pdf,.pdf",True,"Choose PDF files")+"<ul id='list' class='sortlist'></ul><button class='btn' id='go' type='button'>Merge PDFs</button><p id='status' class='status'></p><div id='out'></div>"+PRIV
js="""var files=[];function draw(){var l=UI.$('#list');l.innerHTML='';files.forEach(function(f,i){var li=document.createElement('li');li.innerHTML='<span></span><button type="button" aria-label="Move up">↑</button><button type="button" aria-label="Move down">↓</button><button type="button" aria-label="Remove">✕</button>';li.firstChild.textContent=(i+1)+'. '+f.name+' ('+DK.fileSize(f.size)+')';var b=li.querySelectorAll('button');
b[0].onclick=function(){if(i){files.splice(i-1,0,files.splice(i,1)[0]);draw()}};b[1].onclick=function(){if(i<files.length-1){files.splice(i+1,0,files.splice(i,1)[0]);draw()}};b[2].onclick=function(){files.splice(i,1);draw()};l.appendChild(li)})}
UI.drop(UI.$('#drop'),{multiple:true,onFiles:function(fs){files=files.concat(fs);draw()}});
UI.$('#go').onclick=async function(){if(files.length<2)return UI.status('Add at least two PDFs.',1);UI.status('Merging…');try{var out=await PDFLib.PDFDocument.create(),n=0;for(var i=0;i<files.length;i++){var src;try{src=await PDFLib.PDFDocument.load(await files[i].arrayBuffer())}catch(e){throw new Error(files[i].name+': '+(/encrypt/i.test(e.message)?'this PDF is password-protected. Remove the password first.':'not a valid PDF.'))}
var pg=await out.copyPages(src,src.getPageIndices());pg.forEach(function(p){out.addPage(p)});n+=pg.length}var bytes=await out.save();UI.results([{name:'merged.pdf',blob:new Blob([bytes],{type:'application/pdf'}),note:n+' pages'}]);UI.status('Merged '+files.length+' files into '+n+' pages.')}catch(e){UI.status(e.message,1)}};"""
add("merge-pdf","PDF tools","Merge PDF","Merge PDF Files – Combine PDFs Free, No Upload","Combine multiple PDF files into one in your browser. Drag to add, reorder, merge, download. Your documents are never uploaded.",ui,js,
"<h2>Combine PDFs in the right order</h2><p>Add two or more PDFs, use the arrows to set the order, then click <b>Merge PDFs</b>. Every page of every file is copied into one new document—text stays selectable and quality is unchanged, because pages are copied, not re-rendered.</p><h2>Why merge in the browser?</h2><p>Contracts, payslips and HR forms are confidential. Most online PDF sites upload your files to their servers. This tool uses the open-source pdf-lib library to do the work on your own device, so the files never leave it.</p>"+FAQ(("Can I merge password-protected PDFs?","No. Remove the password first (open the PDF and print/save it without protection)."),("Is there a page limit?","No fixed limit; very large files are limited only by your device's memory."),("Do links and form fields survive?","Page content, text and images are preserved. Some interactive features such as bookmarks may not be carried over.")),libs=("pdf-lib.min.js",))
# split pdf
ui=dropzone("application/pdf,.pdf",False,"Choose a PDF")+"<div class='opts'><p id='info' class='muted'></p><label for='mode'>How to split</label><select id='mode'><option value='ranges'>Extract page ranges</option><option value='each'>Every page as a separate PDF</option></select><label for='rg'>Ranges (e.g. 1-3, 5, 8-end). Each range becomes one file.</label><input id='rg' type='text' value='1'><label class='chk'><input id='one' type='checkbox'> Put all ranges into a single PDF</label></div><button class='btn' id='go' type='button'>Split PDF</button><p id='status' class='status'></p><div id='out'></div>"+PRIV
js="""var src=null,fname='';UI.drop(UI.$('#drop'),{onFiles:async function(fs){try{fname=fs[0].name;src=await PDFLib.PDFDocument.load(await fs[0].arrayBuffer());UI.$('#info').textContent=fname+': '+src.getPageCount()+' pages';UI.status('')}catch(e){src=null;UI.status(/encrypt/i.test(e.message)?'This PDF is password-protected.':'Not a valid PDF.',1)}}});
UI.$('#go').onclick=async function(){if(!src)return UI.status('Choose a PDF first.',1);try{var n=src.getPageCount(),groups=UI.$('#mode').value==='each'?src.getPageIndices().map(function(i){return [i+1]}):DK.parseRanges(UI.$('#rg').value,n);
if(UI.$('#one').checked&&UI.$('#mode').value==='ranges')groups=[[].concat.apply([],groups)];var base=fname.replace(/\\.pdf$/i,''),out=[];
for(var g of groups){var d=await PDFLib.PDFDocument.create(),ps=await d.copyPages(src,g.map(function(x){return x-1}));ps.forEach(function(p){d.addPage(p)});var lab=g.length>1&&groups.length>1?g[0]+'-'+g[g.length-1]:g.length===1?String(g[0]):'selected';
out.push({name:base+'_p'+lab+'.pdf',blob:new Blob([await d.save()],{type:'application/pdf'}),note:g.length+' page(s)'})}UI.results(out);UI.status('Created '+out.length+' file(s).')}catch(e){UI.status(e.message,1)}};"""
add("split-pdf","PDF tools","Split PDF","Split PDF – Extract Pages From a PDF Free, No Upload","Split a PDF into separate files or extract page ranges like 1-3, 5, 8-end. Works offline in your browser; your PDF is never uploaded.",ui,js,
"<h2>Extract just the pages you need</h2><p>Type the pages you want, separated by commas. <code>1-3</code> is pages 1 to 3, <code>5</code> is a single page, and <code>8-end</code> runs to the last page. Each range becomes its own PDF, or tick <b>Put all ranges into a single PDF</b> to get one file with only those pages—handy for removing pages too.</p><h2>Split every page</h2><p>Choose <i>Every page as a separate PDF</i> to break a scanned stack into individual documents, then download them all as a ZIP.</p>"+FAQ(("How do I delete a page from a PDF?","Extract everything except that page into a single PDF—for a 10-page file without page 4, enter 1-3, 5-10 and tick the single-PDF box."),("Is quality affected?","No. Pages are copied as-is, not re-rendered.")),libs=("pdf-lib.min.js",))
# rotate pdf
ui=dropzone("application/pdf,.pdf",False,"Choose a PDF")+"<div class='opts'><p id='info' class='muted'></p><label for='ang'>Rotate</label><select id='ang'><option value='90'>90° clockwise</option><option value='180'>180° (upside down)</option><option value='270'>90° counter-clockwise</option></select><label for='rg'>Pages to rotate (blank = all, e.g. 1-3, 5, 8-end)</label><input id='rg' type='text' placeholder='All pages'></div><button class='btn' id='go' type='button'>Rotate PDF</button><p id='status' class='status'></p><div id='out'></div>"+PRIV
js="""var src=null,fname='';UI.drop(UI.$('#drop'),{onFiles:async function(fs){try{fname=fs[0].name;src=await PDFLib.PDFDocument.load(await fs[0].arrayBuffer());UI.$('#info').textContent=fname+': '+src.getPageCount()+' pages';UI.status('')}catch(e){src=null;UI.status(/encrypt/i.test(e.message)?'This PDF is password-protected.':'Not a valid PDF.',1)}}});
UI.$('#go').onclick=async function(){if(!src)return UI.status('Choose a PDF first.',1);try{var n=src.getPageCount(),r=UI.$('#rg').value.trim(),sel=r?[].concat.apply([],DK.parseRanges(r,n)):src.getPageIndices().map(function(i){return i+1}),a=+UI.$('#ang').value;
var d=await PDFLib.PDFDocument.load(await src.save()),seen={};sel.forEach(function(x){if(seen[x])return;seen[x]=1;var p=d.getPage(x-1);p.setRotation(PDFLib.degrees(((p.getRotation().angle||0)+a)%360))});
UI.results([{name:fname.replace(/\\.pdf$/i,'')+'_rotated.pdf',blob:new Blob([await d.save()],{type:'application/pdf'}),note:Object.keys(seen).length+' of '+n+' page(s) rotated'}]);UI.status('Done.')}catch(e){UI.status(e.message,1)}};"""
add("rotate-pdf","PDF tools","Rotate PDF","Rotate PDF – Rotate Pages Permanently, Free, No Upload","Rotate all pages or only selected pages of a PDF by 90°, 180° or 270° and save the result permanently. Runs in your browser; your PDF is never uploaded.",ui,js,
"<h2>Fix sideways and upside-down pages</h2><p>Scanned contracts and phone scans often come out sideways. Choose your PDF, pick the direction, and click <b>Rotate PDF</b>. Leave the page box empty to rotate every page, or type pages such as <code>2, 4-6</code> or <code>3-end</code> to rotate only those.</p><h2>Rotation that sticks</h2><p>Rotating in a PDF viewer usually only changes the view on your screen. This tool changes the page's rotation setting inside the file, so the pages open the right way up for everyone you send it to, in every PDF reader and when printed.</p><h2>Private by design</h2><p>The rotation is done on your own device with the open-source pdf-lib library. Nothing is uploaded, so it is safe for payslips, IDs and signed documents.</p>"+FAQ(("Does rotating reduce quality?","No. Only the page's rotation flag is changed; text, images and signatures are untouched and text stays selectable."),("Can I rotate pages in different directions?","Yes—run the tool twice: first rotate some pages clockwise, then load the result and rotate other pages counter-clockwise."),("Can I rotate a password-protected PDF?","No. Remove the password first, then rotate it.")),libs=("pdf-lib.min.js",))
# delete pdf pages
ui=dropzone("application/pdf,.pdf",False,"Choose a PDF")+"<div class='opts'><p id='info' class='muted'></p><label for='rg'>Pages to delete (e.g. 2, 5-7, 10-end)</label><input id='rg' type='text' value=''></div><button class='btn' id='go' type='button'>Delete pages</button><p id='status' class='status'></p><div id='out'></div>"+PRIV
js="""var src=null,fname='';UI.drop(UI.$('#drop'),{onFiles:async function(fs){try{fname=fs[0].name;src=await PDFLib.PDFDocument.load(await fs[0].arrayBuffer());UI.$('#info').textContent=fname+': '+src.getPageCount()+' pages';UI.status('')}catch(e){src=null;UI.status(/encrypt/i.test(e.message)?'This PDF is password-protected.':'Not a valid PDF.',1)}}});
UI.$('#go').onclick=async function(){if(!src)return UI.status('Choose a PDF first.',1);try{var n=src.getPageCount(),keep=DK.pagesExcept(DK.parseRanges(UI.$('#rg').value,n),n),d=await PDFLib.PDFDocument.create(),ps=await d.copyPages(src,keep.map(function(x){return x-1}));ps.forEach(function(p){d.addPage(p)});
UI.results([{name:fname.replace(/\\.pdf$/i,'')+'_edited.pdf',blob:new Blob([await d.save()],{type:'application/pdf'}),note:(n-keep.length)+' page(s) deleted, '+keep.length+' left'}]);UI.status('Done.')}catch(e){UI.status(e.message,1)}};"""
add("delete-pdf-pages","PDF tools","Delete PDF Pages","Delete Pages From PDF – Remove PDF Pages Free, No Upload","Remove unwanted pages from a PDF: type the page numbers or ranges to delete and download the new file. Works in your browser; nothing is uploaded.",ui,js,
"<h2>Remove pages in three steps</h2><ol><li>Choose or drop your PDF. The page count is shown.</li><li>Type the pages to delete, separated by commas: <code>2</code> removes one page, <code>5-7</code> removes a range and <code>10-end</code> removes everything from page 10 on.</li><li>Click <b>Delete pages</b> and download the new PDF.</li></ol><h2>Typical uses</h2><ul><li>Drop blank pages from a scanned document.</li><li>Remove a cover page or terms and conditions before sending a quote.</li><li>Take personal pages out of a bank statement before sharing it.</li></ul><h2>Quality and privacy</h2><p>The remaining pages are copied exactly as they were—no re-rendering, so text stays sharp and searchable. The work happens on your own device with the open-source pdf-lib library; the file is never uploaded. To keep only a few pages instead, use <a href='/split-pdf/'>Split PDF</a>.</p>"+FAQ(("Is the original file changed?","No. Your original stays as it is; you download a new copy without the deleted pages."),("Can I delete all pages?","No—at least one page must remain."),("Can I undo a deletion?","Just run the tool again on your original file.")),libs=("pdf-lib.min.js",))
# pdf to jpg
ui=dropzone("application/pdf,.pdf",False,"Choose a PDF")+"<div class='opts'><label for='dpi'>Resolution</label><select id='dpi'><option value='96'>96 DPI (screen)</option><option value='150' selected>150 DPI (good)</option><option value='300'>300 DPI (print)</option></select><label for='fmt'>Format</label><select id='fmt'><option value='image/jpeg'>JPG</option><option value='image/png'>PNG</option></select><label for='rg'>Pages (blank = all)</label><input id='rg' type='text' placeholder='e.g. 1-3, 5'></div><button class='btn' id='go' type='button'>Convert to images</button><p id='status' class='status'></p><div id='out'></div>"+PRIV
js="""var file=null;UI.drop(UI.$('#drop'),{onFiles:function(fs){file=fs[0];UI.status(file.name+' ready.')}});var lib=import('/assets/pdf.min.mjs').then(function(m){m.GlobalWorkerOptions.workerSrc='/assets/pdf.worker.min.mjs';return m});
UI.$('#go').onclick=async function(){if(!file)return UI.status('Choose a PDF first.',1);try{UI.status('Loading PDF…');var pdfjs=await lib,doc=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise,n=doc.numPages,rg=UI.$('#rg').value.trim(),pages=rg?[].concat.apply([],DK.parseRanges(rg,n)):Array.from({length:n},function(_,i){return i+1});
var sc=+UI.$('#dpi').value/72,t=UI.$('#fmt').value,ext=t==='image/png'?'png':'jpg',base=file.name.replace(/\\.pdf$/i,''),out=[];
for(var k=0;k<pages.length;k++){UI.status('Rendering page '+pages[k]+' ('+(k+1)+'/'+pages.length+')…');var pg=await doc.getPage(pages[k]),vp=pg.getViewport({scale:sc}),c=document.createElement('canvas');c.width=Math.round(vp.width);c.height=Math.round(vp.height);var x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);
await pg.render({canvasContext:x,viewport:vp}).promise;var b=await new Promise(function(ok){c.toBlob(ok,t,0.92)});out.push({name:base+'_page'+pages[k]+'.'+ext,blob:b,note:c.width+'×'+c.height})}UI.results(out);UI.status('Converted '+out.length+' page(s).')}catch(e){UI.status(/password/i.test(e.name+e.message)?'This PDF is password-protected.':e.message,1)}};"""
add("pdf-to-jpg","PDF tools","PDF to JPG Converter","PDF to JPG – Convert PDF Pages to Images Free, No Upload","Convert PDF pages to high-quality JPG or PNG images at 96, 150 or 300 DPI. Choose pages, download as ZIP. Runs in your browser, nothing uploaded.",ui,js,
"<h2>Convert PDF pages to images</h2><p>Need a page of a report in a slide deck, a chat message or a CMS that doesn't accept PDFs? Choose the PDF, pick a resolution and which pages, and each page is rendered to an image using Mozilla's pdf.js—the same engine that displays PDFs in Firefox.</p><h2>Which resolution?</h2><ul><li><b>96 DPI:</b> quick previews and thumbnails.</li><li><b>150 DPI:</b> sharp on screens and in slides (a Letter page is 1275 × 1650 px).</li><li><b>300 DPI:</b> printing or zooming into small text (2550 × 3300 px).</li></ul><p>Use PNG for pages that are mostly text or diagrams; JPG for scanned pages and photos.</p>"+FAQ(("Is my PDF uploaded?","No. Rendering happens in your browser."),("Can it extract embedded images?","It renders whole pages. To get an embedded photo, render the page at 300 DPI and crop it.")))
