ui="<div class='tabs'><button type='button' class='tab on' data-m='c2x'>CSV → Excel</button><button type='button' class='tab' data-m='x2c'>Excel → CSV</button></div>"+dropzone(".csv,.txt,.tsv,.xlsx,.xls,.ods,text/csv",False,"Choose a file")+"<div class='opts'><label for='dl'>CSV delimiter</label><select id='dl'><option value='auto'>Auto-detect</option><option value=','>Comma ,</option><option value=';'>Semicolon ;</option><option value='\\t'>Tab</option></select></div><p id='status' class='status'></p><div id='prev' class='tablewrap'></div><div id='out'></div>"+PRIV
js="""var mode='c2x';document.querySelectorAll('.tab').forEach(function(b){b.onclick=function(){document.querySelectorAll('.tab').forEach(function(x){x.classList.toggle('on',x===b)});mode=b.dataset.m;UI.$('#drop b').textContent=mode==='c2x'?'Choose a CSV file':'Choose an Excel file'}});
function preview(rows){var h='<table>'+rows.slice(0,8).map(function(r){return '<tr>'+r.slice(0,10).map(function(c){return '<td>'+DK.esc(c==null?'':c)+'</td>'}).join('')+'</tr>'}).join('')+'</table>';UI.$('#prev').innerHTML=h}
UI.drop(UI.$('#drop'),{onFiles:async function(fs){var f=fs[0];try{var isX=/\\.(xlsx|xls|ods)$/i.test(f.name);var dl=UI.$('#dl').value;dl=dl==='auto'?null:dl.replace('\\\\t','\\t');
if(!isX){var txt=await f.text(),rows=DK.parseCSV(txt,dl);var ws=XLSX.utils.aoa_to_sheet(rows.map(function(r){return r.map(function(v){return /^-?(0|[1-9]\\d{0,14})(\\.\\d+)?$/.test(v)?+v:v})})),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Sheet1');
var out=XLSX.write(wb,{bookType:'xlsx',type:'array'});preview(rows);UI.results([{name:DK.renameExt(f.name,'xlsx'),blob:new Blob([out],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),note:rows.length+' rows'}]);UI.status('Converted CSV to Excel. Numbers are stored as numbers; values like 00123 keep their leading zeros as text.')}
else{var wb=XLSX.read(await f.arrayBuffer()),out=[];wb.SheetNames.forEach(function(sn){var rows=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,raw:false,defval:''});out.push({name:f.name.replace(/\\.[^.]+$/,'')+(wb.SheetNames.length>1?'_'+sn:'')+'.csv',blob:new Blob(['\\uFEFF'+DK.toCSV(rows,dl||',')],{type:'text/csv'}),note:rows.length+' rows'});if(out.length===1)preview(rows)});UI.results(out);UI.status('Converted '+out.length+' sheet(s) to CSV (UTF-8, opens correctly in Excel).')}}catch(e){UI.status('Could not read this file: '+e.message,1)}}});"""
add("csv-to-excel","Spreadsheet tools","CSV to Excel Converter","CSV to Excel (XLSX) and Excel to CSV Converter – No Upload","Convert CSV to Excel XLSX or Excel to CSV in your browser. Auto-detects delimiters, keeps leading zeros, exports every sheet. Files never leave your device.",ui,js,
"<h2>CSV to Excel without the usual problems</h2><p>Opening a CSV directly in Excel can mangle data: leading zeros in ZIP codes and IDs disappear, long numbers turn into scientific notation, and accented characters break. This converter builds a proper .xlsx file where plain numbers are stored as numbers but values like <code>00123</code> or 16-digit IDs stay exactly as written.</p><h2>Excel to CSV</h2><p>Switch to <b>Excel → CSV</b> and drop an .xlsx, .xls or .ods file. Every sheet is exported as its own CSV in UTF-8 with a byte-order mark, so it re-opens correctly in Excel and imports cleanly into databases and CRMs.</p><h2>Delimiters</h2><p>European exports often use semicolons. Auto-detect handles comma, semicolon, tab and pipe; you can also pick one manually.</p>"+FAQ(("Is my spreadsheet uploaded?","No. Conversion uses the SheetJS library inside your browser."),("Are formulas kept when exporting to CSV?","CSV can only hold values, so each cell's displayed value is exported.")),libs=("xlsx.full.min.js",))
